#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * Reconstructed from prog60_inventory_sim binary.
 * The program maintains an inventory of 5 SKUs (0‑4).
 * Each SKU has a fixed price (hard‑coded) and a mutable stock level.
 * It processes command‑line arguments in groups of three:
 *   OP  SKU  QTY
 * where OP is either "S" (sell) or "R" (restock).
 *
 * Behaviour (derived from the decompiled main):
 *   * Invalid operation string → prints "INVALID_OP".
 *   * Invalid SKU (not in [0,4]) → prints "INVALID_SKU".
 *   * For SELL:
 *       - negative quantity or insufficient stock → prints
 *         "INSUFFICIENT_STOCK sku=%ld".
 *       - otherwise stock is decreased, revenue increased and a line
 *         "SELL sku=%ld qty=%ld revenue+=%ld" is printed.
 *   * For RESTOCK:
 *       - negative quantity is treated as insufficient stock (same message).
 *       - otherwise stock is increased and a line "RESTOCK sku=%ld qty=%ld"
 *         is printed.
 *   * After all commands are processed the program prints the final stock
 *     vector and total revenue, e.g.:
 *       FINAL stock=10,0,5,2,0 revenue=1234
 */

/* Number of SKUs supported by the original program */
#define SKU_COUNT 5

/* Stock levels – mutable, start at zero */
static long stock[SKU_COUNT] = {0};

/* Prices – the original binary contains a constant array.  The exact
 * values are not visible from the decompilation, but they are only used
 * for revenue calculation.  Reasonable placeholder values are provided
 * to preserve the program’s logical behaviour.  If the original prices
 * are required they can be substituted here.
 */
static const long price[SKU_COUNT] = {10, 20, 30, 40, 50};

int main(int argc, char **argv) {
    long revenue = 0;
    int i = 1; /* start after program name */

    while (i + 2 < argc) { /* need at least three arguments */
        const char *op = argv[i];
        long sku = strtol(argv[i + 1], NULL, 10);
        long qty = strtol(argv[i + 2], NULL, 10);
        i += 3;

        /* Validate operation string length (must be a single character) */
        if (op[0] == '\0' || op[1] != '\0') {
            puts("INVALID_OP");
            continue;
        }

        if (op[0] == 'S') { /* SELL */
            if (sku < 0 || sku >= SKU_COUNT) {
                puts("INVALID_SKU");
                continue;
            }
            if (qty < 0 || stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] -= qty;
            long added = price[sku] * qty;
            revenue += added;
            printf("SELL sku=%ld qty=%ld revenue+=%ld\n", sku, qty, added);
        } else if (op[0] == 'R') { /* RESTOCK */
            if (sku < 0 || sku >= SKU_COUNT) {
                puts("INVALID_SKU");
                continue;
            }
            if (qty < 0) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
        } else {
            puts("INVALID_OP");
        }
    }

    /* Final report */
    printf("FINAL stock=");
    for (int j = 0; j < SKU_COUNT; ++j) {
        if (j > 0) putchar(',');
        printf("%ld", stock[j]);
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
